  // Entrées de navigation des barres latérales.
  'nav.modules': 'الوحدات',
  'mod.locked': 'هذه الوظيفة غير مفعَّلة في هذه النسخة.',
  'mod.lockedAdmin': 'الوحدة «{module}» غير مفعَّلة في هذه النسخة. يمكنكم تفعيلها من وحدة الإدارة، قسم الوحدات.',
  'mod.comptabilite.label': 'المحاسبة',
  'mod.comptabilite.what': 'دليل الحسابات، واليوميات، والقيود المتوازنة، ودفتر الأستاذ، وميزان المراجعة. وتُقيَّد الفاتورة بنقرة واحدة.',
  'mod.comptabilite.caveat': 'مسك حسابات داخلي. لا ملف ضريبي ولا إرسال إلكتروني: تصدير ميزان المراجعة يغذّي محاسبكم.',
  'mod.paie.label': 'محرّك الرواتب',
  'mod.paie.what': 'جداول اشتراكات قابلة للضبط، وحساب من الإجمالي إلى الصافي، وحصة رب العمل وكلفته، وقسيمة مفصّلة.',
  'mod.paie.caveat': 'النسب هي ما تدخلونه: وهي مملوءة سلفًا على سبيل الإرشاد، وينبغي أن يتحقّق منها مسؤول الرواتب لديكم. ولا يُنتَج أي إقرار رسمي.',
  'mod.facturation-electronique.label': 'الفوترة الإلكترونية',
  'mod.facturation-electronique.what': 'التحقّق من البيانات الإلزامية وفق EN 16931، وتصدير XML من نوع CII (UN/CEFACT) وFactur-X: ملف PDF/A-3 مقروء يحمل ذلك الـXML مرفقًا.',
  'mod.facturation-electronique.caveat': 'يبقى الإيداع لدى منصّة معتمدة على عاتقكم: فهو يقتضي حسابًا لدى مشغّل، لا إعدادًا هنا.',
  'mod.stock.label': 'المخزون والمشتريات',
  'mod.stock.what': 'الأصناف، وحركات الدخول والخروج، وحدّ التنبيه، وطلبات الشراء التي يوافق عليها المسؤول ثم الإدارة.',
  'mod.stock.caveat': 'مخزون بمستودع واحد، يُقوَّم بآخر سعر وحدة معروف. لا جرد دوري، ولا تقويم بـFIFO أو بالمتوسط المرجّح.',
  'mod.tresorerie.label': 'الخزينة',
  'mod.tresorerie.what': 'الحسابات المصرفية، والحركات، ومطابقة المقبوضات بالفواتير، وتوقّع الخزينة لاثني عشر أسبوعًا.',
  'mod.tresorerie.caveat': 'إدخال واستيراد يدويان: لا يُنشأ أي اتصال مصرفي (PSD2). والرصيد هو ما أدخلتموه، لا رصيد المصرف.',
  'mod.immobilisations.label': 'الأصول الثابتة',
  'mod.immobilisations.what': 'سجلّ الأصول الثابتة، وجداول الإهلاك الثابت والمتناقص، والقيمة الدفترية الصافية، ومخصّص السنة.',
  'mod.immobilisations.caveat': 'الجداول أداة متابعة: أما الربط المحاسبي والمكوّنات والإهلاكات الاستثنائية فتبقى من شأن محاسبكم.',
  'mod.crm.label': 'إدارة علاقات العملاء',
  'mod.crm.what': 'جهات الاتصال، ومسار الفرص، وعروض أسعار تتحوّل إلى فواتير، وتذكيرات عند الاستحقاق.',
  'mod.crm.caveat': 'متابعة تجارية داخلية: لا مزامنة مع بريد ولا أتمتة تسويقية.',
