  'sec.pilotage.intro': 'القيادة تجمع الأرقام التي تنظر إليها الإدارة العليا: عدد العاملين، ورقم الأعمال، والمستحقات غير المحصَّلة، والأهداف، والاستحقاقات القادمة. لا تعيد حساب شيء، بل تجمع ما تمسكه الأقسام الأخرى أصلاً.',
  'sec.personnel.intro': 'الأفراد يمسك الناس: الملفات والعقود والإجازات والجدولة والمسارات والصحة والسلامة. هو القسم الأشدّ حساسية في بياناته، والأكثر استعمالاً.',
