  'sec.relation.intro': 'العلاقات تمسك ما يأتي من الخارج كما من الداخل: الطلبات والتذاكر وقاعدة المعرفة والاستقبال والفعاليات والأخبار.',
  'sec.technique.intro': 'التقنية تمسك النسخة نفسها: العتاد المعلوماتي والتكاملات والتحديثات والنسخ الاحتياطية والسجلات والاستيراد.',
  'sec.conformite.intro': 'الامتثال يمسك ما يُطلَب منكم: أمن الحسابات وحماية البيانات والحياة القانونية والتوقيعات. هو القسم الذي يُفتَح يوم التفتيش.',
  'sec.reglages.intro': 'الإعدادات تمسك النسخة: هوية الشركة واللغة والمظهر والوحدات والتطبيقات. هذا القسم لا يُزال، فهو الذي يتيح إعادة الأقسام الأخرى.',
